/*--------------------------------------------------------------------*/
/*--- REP bulk cost model: calibrated hot-copy curve.              ---*/
/*---                                                    rep_bulk.c ---*/
/*--------------------------------------------------------------------*/

/* CodSpeed extension. See rep_bulk.h. */

#include "rep_bulk.h"
#include "pub_tool_libcassert.h"

/* Generated by the calibration pipeline. Defines
 * clg_rep_bulk_provenance[], clg_rep_bulk_pts_<id>[] and
 * clg_rep_bulk_curves[] (types from rep_bulk.h). */
#include "rep_bulk_table.inc"

#define N_CURVES ((UInt)(sizeof(clg_rep_bulk_curves) / \
                         sizeof(clg_rep_bulk_curves[0])))

#define N_WIDTHS 4
#define N_DIRS   2
#define N_ALIGN  3

/* The generated table lists the curves in key order: op, width, direction,
 * alignment class. */
static const ClgRepBulkCurve* curve(unsigned op, unsigned elem_width,
                                    unsigned direction, unsigned align_class)
{
   UInt w = (UInt)__builtin_ctz(elem_width);
   return &clg_rep_bulk_curves[(((op - CLG_REP_OP_MOVS) * N_WIDTHS + w)
                                * N_DIRS + direction) * N_ALIGN + align_class];
}

/* Interpolate linearly between the neighbouring sampled byte sizes. Integer
 * floor rounding keeps the result monotone, so marginal costs never become
 * negative (consecutive element deltas telescope exactly for the same F). */
static ULong cost_at(const ClgRepBulkCurve* c, ULong bytes)
{
   const ClgRepBulkPoint* p = c->pts;
   UInt                   n = c->npts;

   if (bytes <= p[0].bytes)
      return p[0].centicycles;

   /* Last point <= bytes. */
   UInt lo = 0, hi = n - 1;
   while (lo < hi) {
      UInt mid = lo + (hi - lo + 1) / 2;
      if (p[mid].bytes <= bytes)
         lo = mid;
      else
         hi = mid - 1;
   }

   if (p[lo].bytes == bytes)
      return p[lo].centicycles;

   /* Beyond the last sampled size, extend the last segment's slope. */
   if (lo + 1 == n)
      lo--;

   ULong dbytes = (ULong)(p[lo + 1].bytes - p[lo].bytes);
   ULong dcost = p[lo + 1].centicycles - p[lo].centicycles;
   ULong off = bytes - p[lo].bytes;
   return p[lo].centicycles + (off * dcost) / dbytes;
}

void clg_rep_bulk_init(void)
{
   UInt i;

   (void)clg_rep_bulk_provenance;
   tl_assert(N_CURVES == 2 * N_WIDTHS * N_DIRS * N_ALIGN);
   for (i = 0; i < N_CURVES; i++) {
      const ClgRepBulkCurve* c = &clg_rep_bulk_curves[i];
      tl_assert(c->npts >= 2);
      tl_assert(curve(c->key.op, c->key.elem_width, c->key.direction,
                      c->key.align_class) == c);
   }
}

ULong clg_rep_bulk_marginal(unsigned op, unsigned elem_width,
                            unsigned direction, unsigned align_class,
                            ULong remaining_bytes, ULong elem_bytes)
{
   const ClgRepBulkCurve* c = curve(op, elem_width, direction, align_class);

   /* F is monotone, so the difference is never negative and telescopes to
    * F(total) over one operation. */
   return cost_at(c, remaining_bytes) - cost_at(c, remaining_bytes - elem_bytes);
}

/* Prefixes followed by A4/A5/AA/AB; REX must directly precede the opcode. */
void clg_rep_bulk_classify(const unsigned char* bytes, unsigned len,
                           ClgRepBulkInfo* out)
{
   out->op = CLG_REP_OP_NONE;
   out->elem_width = 0;
#if defined(VGA_amd64)
   unsigned i = 0;
   int      rep = 0, opsz16 = 0, addr32p = 0, rex_w = 0;

   if (!bytes || len < 2 || len > 15)
      return;

   while (i < len) {
      unsigned char c = bytes[i];
      if (c == 0xF3 && !rep) {
         rep = 1;
         i++;
         continue;
      }
      if (c == 0xF2)
         return; /* REPNE: never a supported bulk copy */
      if (c == 0x66 && !opsz16) {
         opsz16 = 1;
         i++;
         continue;
      }
      if (c == 0x67 && !addr32p) {
         addr32p = 1;
         i++;
         continue;
      }
      if (c >= 0x40 && c <= 0x4F) {
         rex_w = (c & 0x08) != 0;
         i++;
      }
      break;
   }

   /* Exactly the opcode must follow the prefix run: no operands, no
    * trailing bytes (the IMark length always covers the whole insn). */
   if (!rep || i + 1 != len)
      return;

   switch (bytes[i]) {
   case 0xA4: /* movsb */
      out->op = CLG_REP_OP_MOVS;
      out->elem_width = 1;
      break;
   case 0xA5: /* movsw/movsd/movsq */
      out->op = CLG_REP_OP_MOVS;
      out->elem_width = rex_w ? 8 : (opsz16 ? 2 : 4);
      break;
   case 0xAA: /* stosb */
      out->op = CLG_REP_OP_STOS;
      out->elem_width = 1;
      break;
   case 0xAB: /* stosw/stosd/stosq */
      out->op = CLG_REP_OP_STOS;
      out->elem_width = rex_w ? 8 : (opsz16 ? 2 : 4);
      break;
   }
#else
   (void)bytes;
   (void)len;
#endif
}
